import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"1967年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1967年/核心总结.md","filePath":"01_letters/1967年/核心总结.md"}'),n={name:"01_letters/1967年/核心总结.md"};function l(i,a,s,_,d,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1967年-核心总结" tabindex="-1">1967年 核心总结 <a class="header-anchor" href="#_1967年-核心总结" aria-label="Permalink to &quot;1967年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1967年，道琼斯指数上涨19%，而巴菲特合伙企业取得35.9%的收益率，继续保持约17个百分点的超额收益。合伙企业净资产从4364万美元增长至5400万美元以上。这一年，巴菲特在信中正式下调了长期年均收益目标——从此前隐含的&quot;显著跑赢指数&quot;调整为年均9%的明确目标，反映了他对市场机会收窄与资金规模扩张的务实评估。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>巴菲特在这一年推进了两项重要收购：一是联合棉花商店（Union Cotton），这是他自伯克希尔纺织业务延伸出来的零售整合动作；二是国民赔偿保险公司（National Indemnity），一家小型财产与意外险公司。这两项收购都具有共同的特征：稳定的现金流、低于内在价值的估值，以及与巴菲特已有能力圈的高度契合。特别是国民赔偿保险的收购，为此后巴菲特构建保险帝国奠定了关键基础。</p><p>在投资组合层面，巴菲特继续加大在保险板块的布局。他敏锐地意识到，保险浮存金（float）是一种具有战略价值的杠杆来源——可以用于投资而不增加负债成本，这成为日后伯克希尔体系的核心财务机制之一。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特在1967年的信中展现出罕见的坦诚：长期来看，合伙企业的年均收益率可能难以维持在显著高于9%的水平。这一目标的下调，是他基于资金规模、市场估值水平以及机会成本综合权衡的结果，也体现了&quot;诚实面对现实&quot;的投资哲学。他告诫合伙人：接受合理的回报，比追逐不切实际的高收益更为理性。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>杰克·邓福德（Jack Dunford）作为国民赔偿保险的核心人物之一，在收购完成后与巴菲特建立了深度信任关系。与此同时，阿斯特丽德·麦克斯韦尔（Astrid Maxwell）等家族成员的资产持续由巴菲特管理，证明了其口碑在特定圈层中的高度传播。</p>',10)])])}const u=e(n,[["render",l]]);export{p as __pageData,u as default};
